12	const PROCESSING_FEE = 5;
13	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
14	
15	const BASE_PREMIUMS: Record<string, number> = {
16	  sword: 100,
17	  amulet: 60,
18	  staff: 80,
19	  potion: 40,
20	  rune: 25,
21	  moonstone: 25,
22	};
23	
24	const COMPONENT_PREMIUM = 25;
25	const BLOCK_SIZE = 3;
26	const BLOCK_PREMIUM = 60;
27	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
28	
29	const percentOf = (amount: number, percent: number): number =>
30	  (amount * percent) / 100;
31	
32	const basePremium = (item: Item): number => BASE_PREMIUMS[item.type] ?? 0;
33	
34	const componentGroupPremium = (count: number): number =>
35	  count === BLOCK_SIZE ? BLOCK_PREMIUM : count * COMPONENT_PREMIUM;
36	
37	const applyFirstInsuranceSurcharge = (amount: number): number =>
38	  amount + percentOf(amount, FIRST_INSURANCE_SURCHARGE_PERCENT);
39	
40	const roundInMhpcoFavor = (premium: number): number => Math.ceil(premium);
41	
42	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
43	
44	const isMainItem = (item: Item): boolean => !isComponent(item);
45	
46	const countByType = (components: Item[]): Map<string, number> => {
47	  const counts = new Map<string, number>();
48	  for (const component of components) {
49	    counts.set(component.type, (counts.get(component.type) ?? 0) + 1);
50	  }
51	  return counts;
52	};
53	
54	const componentsTotalByType = (components: Item[]): number =>
55	  [...countByType(components).values()].reduce(
56	    (total, count) => total + componentGroupPremium(count),
57	    0,
58	  );
59	
60	const itemsBasePremium = (items: Item[]): number => {
61	  const components = items.filter(isComponent);
62	  const mainItems = items.filter(isMainItem);
63	  const mainItemsTotal = mainItems.reduce(
64	    (sum, item) => sum + basePremium(item),
65	    0,
66	  );
67	  return mainItemsTotal + componentsTotalByType(components);
68	};
69	
70	const CURSE_SURCHARGE_PERCENT = 50;
71	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
72	const HIGH_ENCHANTMENT_THRESHOLD = 5;
73	
74	const itemSurcharge = (item: Item): number => {
75	  const base = basePremium(item);
76	  const curse = item.cursed ? percentOf(base, CURSE_SURCHARGE_PERCENT) : 0;
77	  const highEnchantment =
78	    (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
79	      ? percentOf(base, HIGH_ENCHANTMENT_SURCHARGE_PERCENT)
80	      : 0;
81	  return curse + highEnchantment;
82	};
83	
84	const itemSurcharges = (items: Item[]): number =>
85	  items.reduce((sum, item) => sum + itemSurcharge(item), 0);
86	
87	export const quote = (
88	  customer: Customer,
89	  items: Item[],
90	  contractIndex: number,
91	): number => {
92	  const base = itemsBasePremium(items);
93	  const total =
94	    applyFirstInsuranceSurcharge(base) + itemSurcharges(items) + PROCESSING_FEE;
95	  return roundInMhpcoFavor(total);
96	};
97	
98	export const claim = (): number => {
99	  return undefined as unknown as number;
100	};
